/// Which way round that chart is played. Absent is `countdown`, which ends on number one. Ignored without `sourceChartId`
public enum ScheduleSlotSourceChartOrder: String, Codable, CaseIterable, Sendable {
    case countdown = "countdown"
    case ranked = "ranked"
    case unordered = "unordered"
}

/// The mood this stretch of the day leans into. Records a model has judged to be in it are a little more likely to be picked; nothing is ever kept off the air for it. Absent is no lean
public enum ScheduleSlotMood: String, Codable, CaseIterable, Sendable {
    case love = "love"
    case happiness = "happiness"
    case comfort = "comfort"
    case sadness = "sadness"
    case loneliness = "loneliness"
    case anger = "anger"
    case fear = "fear"
}

public enum ScheduleSlotMode: String, Codable, CaseIterable, Sendable {
    case rotation = "rotation"
    case setlist = "setlist"
    case feature = "feature"
}

public enum ScheduleSlotOnEnd: String, Codable, CaseIterable, Sendable {
    case extend = "extend"
    case `repeat` = "repeat"
    case stop = "stop"
}
